/**
 * 四川质控规则演示用例库
 *
 * 为每条规则提供更贴合质控点的正例/反例。
 * 所有案例均为虚构或脱敏内容，仅用于前端演示。
 */

export interface QCCaseSection {
  heading: string
  content: string
  hint?: string
}

export interface QCRuleCaseExample {
  title: string
  summary: string
  sections: QCCaseSection[]
  focusPoints: string[]
}

export interface QCRuleCase {
  ruleId: string
  documentType: string
  positive: QCRuleCaseExample
  negative: QCRuleCaseExample
}

export interface BuildCaseTextOptions {
  includeHints?: boolean // 是否包含提示信息（默认 false，避免干扰 LLM 评估）
  includeFocusPoints?: boolean // 是否包含质控关注点（默认 false）
  includeTitle?: boolean // 是否包含标题和摘要（默认 true）
  includeAnalysis?: boolean // 是否包含分析性章节（如"分析"、"影响"、"建议"等，默认 false）
}

// 判断是否为分析性章节（用于教学说明，不应包含在病历正文中）
const isAnalysisSection = (heading: string): boolean => {
  const analysisKeywords = ['分析', '影响', '建议', '风险', '评定', '整改', '缺失']
  return analysisKeywords.some(keyword => heading.includes(keyword))
}

const joinSections = (sections: QCCaseSection[], includeHints = false, includeAnalysis = false): string =>
  sections
    .filter(section => includeAnalysis || !isAnalysisSection(section.heading))
    .map(section => {
      const lines = [`【${section.heading}】`, section.content.trim()]
      if (includeHints && section.hint) {
        lines.push(`（提示：${section.hint.trim()}）`)
      }
      return lines.join('\n')
    })
    .join('\n\n')

export const buildCaseText = (
  example: QCRuleCaseExample,
  options: BuildCaseTextOptions = {}
): string => {
  const {
    includeHints = false,
    includeFocusPoints = false,
    includeTitle = true,
    includeAnalysis = false
  } = options

  const header = includeTitle ? `《${example.title}》\n${example.summary}\n\n` : ''
  const body = joinSections(example.sections, includeHints, includeAnalysis)
  const focus =
    includeFocusPoints && example.focusPoints.length > 0
      ? `\n\n【质控关注点】\n- ${example.focusPoints.join('\n- ')}`
      : ''

  return `${header}${body}${focus}`.trim()
}

/**
 * 提取示例中的所有提示信息（包括 hint 字段和分析性章节）
 */
export const extractHints = (example: QCRuleCaseExample): string[] => {
  const hints: string[] = []

  // 提取 hint 字段
  example.sections.forEach(s => {
    if (s.hint) {
      hints.push(s.hint)
    }
  })

  // 提取分析性章节内容
  example.sections.forEach(s => {
    if (isAnalysisSection(s.heading)) {
      hints.push(`${s.heading}：${s.content}`)
    }
  })

  return hints
}

/**
 * 提取质控关注点
 */
export const extractFocusPoints = (example: QCRuleCaseExample): string[] => {
  return example.focusPoints
}



