      summary: "\u5b8c\u6574\u8bb0\u5f55\u4e86\u75c5\u4f8b\u7279\u70b9\u3001\u62df\u8bca\u8ba8\u8bba\u53ca\u8bca\u7597\u8ba1\u5212\uff0c\u7b26\u54088\u5c0f\u65f6\u5185\u5b8c\u6210\u8981\u6c42",
      sections: [
        { heading: "\u60a3\u8005\u57fa\u672c\u60c5\u51b5", content: "\u60a3\u8005\uff0c\u7537\u6027\uff0c62\u5c81\uff0c\u56e0\u2018\u7a81\u53d1\u80f8\u75db\u4f34\u5927\u6c573\u5c0f\u65f6\u2019\u4e8e2024\u5e744\u67085\u65e514:20\u5165\u9662\u3002\u65e2\u5f80\u9ad8\u8840\u538b\u75c5\u53f210\u5e74\uff0c\u672a\u89c4\u5f8b\u670d\u836f\uff1b\u7cd6\u5c3f\u75c5\u53f25\u5e74\uff0c\u53e3\u670d\u4e8c\u7532\u53cc\u80cd\u63a7\u5236\uff1b\u5438\u70df\u53f230\u5e74\uff0c\u6bcf\u65e5\u7ea61\u5305\u3002\u65e0\u836f\u7269\u8fc7\u654f\u53f2\u3002\u5165\u9662\u67e5\u4f53\uff1aT 36.7\u2103\uff0cP 98\u6b21/\u5206\uff0cR 20\u6b21/\u5206\uff0cBP 145/90 mmHg\u3002\u795e\u5fd7\u6e05\u695a\uff0c\u53e3\u5507\u65e0\u53d1\u7ec0\uff0c\u9888\u9759\u8109\u65e0\u6012\u5f20\uff0c\u53cc\u80ba\u547c\u5438\u97f3\u6e05\uff0c\u672a\u95fb\u53ca\u5e72\u6e7f\u5570\u97f3\u3002\u5fc3\u754c\u4e0d\u5927\uff0c\u5fc3\u738798\u6b21/\u5206\uff0c\u5f8b\u9f50\uff0c\u5fc3\u5c16\u90e8\u53ef\u95fb\u53ca2/6\u7ea7\u6536\u7f29\u671f\u6742\u97f3\u3002\u8179\u90e8\u5e73\u8f6f\uff0c\u65e0\u538b\u75db\u53cd\u8df3\u75db\uff0c\u809d\u813e\u808b\u4e0b\u672a\u89e6\u53ca\uff0c\u53cc\u4e0b\u80a2\u65e0\u6c34\u80bf\u3002" },
        { heading: "\u75c5\u4f8b\u7279\u70b9", content: "1. \u4e2d\u8001\u5e74\u7537\u6027\uff0c\u6709\u9ad8\u8840\u538b\u3001\u7cd6\u5c3f\u75c5\u3001\u957f\u671f\u5438\u70df\u7b49\u51a0\u5fc3\u75c5\u9ad8\u5371\u56e0\u7d20\uff1b2. \u7a81\u53d1\u6301\u7eed\u6027\u80f8\u75db3\u5c0f\u65f6\uff0c\u4f4d\u4e8e\u80f8\u9aa8\u540e\uff0c\u5411\u5de6\u80a9\u653e\u5c04\uff0c\u4f34\u5927\u6c57\uff0c\u75c7\u72b6\u4e0e\u6d3b\u52a8\u65e0\u5173\uff0c\u4f11\u606f\u4e0d\u80fd\u7f13\u89e3\uff1b3. \u5fc3\u7535\u56fe\u793a\uff1aV1-V4\u5bfc\u8054ST\u6bb5\u5f13\u80cc\u5411\u4e0a\u62ac\u9ad8\uff0cT\u6ce2\u5012\u7f6e\uff0c\u63d0\u793a\u6025\u6027\u524d\u58c1\u5fc3\u808c\u6897\u6b7b\uff1b4. \u5fc3\u808c\u9176\u8c31\uff1a\u808c\u9499\u86cb\u767dI 8.6 ng/mL\uff08\u2191\uff09\uff0cCK-MB 68 U/L\uff08\u2191\uff09\uff0cLDH 320 U/L\uff08\u2191\uff09\uff1b5. \u8d85\u58f0\u5fc3\u52a8\u56fe\u793a\uff1a\u524d\u58c1\u8fd0\u52a8\u51cf\u5f31\uff0cLVEF 48%\u3002\u7efc\u5408\u4e0a\u8ff0\u8868\u73b0\uff0c\u652f\u6301\u6025\u6027\u524d\u58c1\u5fc3\u808c\u6897\u6b7b\u8bca\u65ad\u3002" },
        { heading: "\u62df\u8bca\u8ba8\u8bba", content: "\u521d\u6b65\u8bca\u65ad\uff1a\u6025\u6027\u524d\u58c1\u5fc3\u808c\u6897\u6b7b\uff08Killip I\u7ea7\uff09\u3002\u9274\u522b\u8bca\u65ad\uff1a1. \u4e3b\u52a8\u8109\u5939\u5c42\uff1a\u591a\u8868\u73b0\u4e3a\u6495\u88c2\u6837\u5267\u70c8\u75bc\u75db\uff0c\u5e38\u5411\u80cc\u90e8\u653e\u5c04\uff0c\u8840\u538b\u5dee\u5f02\u660e\u663e\uff0c\u672c\u4f8b\u65e0\u76f8\u5173\u8868\u73b0\uff0c\u4e14\u5fc3\u7535\u56fe\u4e0d\u652f\u6301\uff0c\u53ef\u80fd\u6027\u4f4e\uff1b2. \u80ba\u6813\u585e\uff1a\u53ef\u6709\u80f8\u75db\u3001\u547c\u5438\u56f0\u96be\uff0c\u4f46\u5e38\u4f34\u6709\u54af\u8840\u3001\u4f4e\u6c27\u8840\u75c7\uff0cD-\u4e8c\u805a\u4f53\u5347\u9ad8\uff0c\u672c\u4f8b\u65e0\u76f8\u5173\u75c7\u72b6\u53ca\u5b9e\u9a8c\u5ba4\u5f02\u5e38\uff0c\u6682\u4e0d\u652f\u6301\uff1b3. \u6025\u6027\u5fc3\u5305\u708e\uff1a\u80f8\u75db\u591a\u968f\u4f53\u4f4d\u6539\u53d8\u800c\u53d8\u5316\uff0c\u5fc3\u7535\u56fe\u5448\u5e7f\u6cdb\u5bfc\u8054ST\u6bb5\u62ac\u9ad8\uff0c\u65e0\u75c5\u7406\u6027Q\u6ce2\uff0c\u672c\u4f8b\u4e0d\u7b26\u5408\u3002\u7ed3\u5408\u4e34\u5e8a\u8868\u73b0\u3001\u5fc3\u7535\u56fe\u53ca\u5fc3\u808c\u6807\u5fd7\u7269\uff0c\u8003\u8651\u6025\u6027\u5fc3\u808c\u6897\u6b7b\u53ef\u80fd\u6027\u5927\u3002" },
        { heading: "\u8bca\u7597\u8ba1\u5212", content: "1. \u7acb\u5373\u542f\u52a8\u6025\u6027\u5fc3\u808c\u6897\u6b7b\u6551\u6cbb\u6d41\u7a0b\uff0c\u6025\u8bca\u884c\u51a0\u72b6\u52a8\u8109\u9020\u5f71\u53ca\u4ecb\u5165\u6cbb\u7597\uff08PCI\uff09\uff1b2. \u5438\u6c27\uff0c\u5fc3\u7535\u76d1\u62a4\uff0c\u5efa\u7acb\u9759\u8109\u901a\u8def\uff1b3. \u963f\u53f8\u5339\u6797300 mg\u56bc\u670d\uff0c\u6c2f\u5421\u683c\u96f7300 mg\u53e3\u670d\uff0c\u809d\u7d20\u6297\u51dd\uff1b4. \u8bc4\u4f30\u6eb6\u6813\u6307\u5f81\uff0c\u82e5\u65e0\u6cd5\u53ca\u65f6\u884cPCI\uff0c\u5219\u8003\u8651\u6eb6\u6813\u6cbb\u7597\uff1b5. \u76d1\u6d4b\u751f\u547d\u4f53\u5f81\u3001\u5fc3\u7535\u56fe\u53ca\u5fc3\u808c\u9176\u52a8\u6001\u53d8\u5316\uff1b6. \u5b8c\u5584\u5fc3\u810f\u8d85\u58f0\u3001\u8840\u8102\u3001\u8840\u7cd6\u3001\u80be\u529f\u80fd\u7b49\u68c0\u67e5\uff1b7. \u544a\u77e5\u75c5\u60c5\u53ca\u6cbb\u7597\u65b9\u6848\uff0c\u7b7e\u7f72\u77e5\u60c5\u540c\u610f\u4e66\u3002" }
      ],
      focusPoints: ["\u660e\u786e\u5217\u51fa\u75c5\u4f8b\u7279\u70b9\uff0c\u6db5\u76d6\u5371\u9669\u56e0\u7d20\u3001\u5178\u578b\u75c7\u72b6\u3001\u8f85\u52a9\u68c0\u67e5\u7ed3\u679c\u53ca\u7efc\u5408\u5224\u65ad"]
