      summary: "\u5b8c\u6574\u6db5\u76d6\u7b80\u8981\u75c5\u60c5\u3001\u672f\u524d\u8bca\u65ad\u3001\u624b\u672f\u6307\u5f81\u3001\u62df\u65bd\u624b\u672f\u540d\u79f0\u548c\u65b9\u5f0f\u3001\u62df\u65bd\u9ebb\u9189\u65b9\u5f0f\u3001\u6ce8\u610f\u4e8b\u9879\u53ca\u624b\u672f\u8005\u672f\u524d\u67e5\u770b\u60c5\u51b5",
      sections: [
        { heading: "\u7b80\u8981\u75c5\u60c5", content: "\u60a3\u8005\u7537\u6027\uff0c58\u5c81\uff0c\u56e0\u53cd\u590d\u53f3\u4e0a\u8179\u9690\u75db\u4f34\u6076\u5fc33\u4e2a\u6708\u5165\u9662\u3002\u65e2\u5f80\u6709\u9ad8\u8840\u538b\u75c5\u53f25\u5e74\uff0c\u89c4\u5f8b\u670d\u836f\u63a7\u5236\u826f\u597d\u3002\u67e5\u4f53\uff1a\u4f53\u6e2936.7\u2103\uff0c\u8109\u640f78\u6b21/\u5206\uff0c\u547c\u543818\u6b21/\u5206\uff0c\u8840\u538b138/86mmHg\u3002\u53f3\u4e0a\u8179\u538b\u75db\u9633\u6027\uff0c\u58a8\u83f2\u5f81\u53ef\u7591\u9633\u6027\u3002\u8179\u90e8B\u8d85\u63d0\u793a\u80c6\u56ca\u58c1\u589e\u539a\uff0c\u80c6\u56ca\u5185\u53ef\u89c1\u591a\u4e2a\u7ed3\u77f3\uff0c\u6700\u5927\u76f4\u5f84\u7ea61.2cm\uff0c\u80c6\u603b\u7ba1\u672a\u89c1\u6269\u5f20\u3002\u809d\u529f\u80fd\u6b63\u5e38\uff0c\u8840\u5e38\u89c4\u65e0\u660e\u663e\u5f02\u5e38\u3002" },
        { heading: "\u672f\u524d\u8bca\u65ad", content: "1. \u6162\u6027\u7ed3\u77f3\u6027\u80c6\u56ca\u708e\uff1b2. \u9ad8\u8840\u538b\u75c52\u7ea7\uff08\u4f4e\u5371\uff09" },
        { heading: "\u624b\u672f\u6307\u5f81", content: "\u60a3\u8005\u53cd\u590d\u53f3\u4e0a\u8179\u75db\uff0c\u5f71\u50cf\u5b66\u8bc1\u5b9e\u80c6\u56ca\u591a\u53d1\u7ed3\u77f3\u4f34\u80c6\u56ca\u58c1\u589e\u539a\uff0c\u4fdd\u5b88\u6cbb\u7597\u65e0\u6548\uff0c\u7b26\u5408\u8179\u8154\u955c\u80c6\u56ca\u5207\u9664\u672f\u6307\u5f81\u3002\u65e0\u660e\u663e\u624b\u672f\u7981\u5fcc\u8bc1\uff0c\u5177\u5907\u624b\u672f\u6761\u4ef6\u3002" },
        { heading: "\u62df\u65bd\u624b\u672f\u540d\u79f0\u548c\u65b9\u5f0f", content: "\u8179\u8154\u955c\u4e0b\u80c6\u56ca\u5207\u9664\u672f\uff08Laparoscopic Cholecystectomy\uff09\uff0c\u91c7\u7528\u56db\u5b54\u6cd5\uff0c\u672f\u4e2d\u884c\u80c6\u56ca\u52a8\u8109\u4e0e\u80c6\u56ca\u7ba1\u89e3\u5256\u5206\u79bb\uff0c\u786e\u8ba4\u80c6\u9053\u7ed3\u6784\u6e05\u6670\u540e\u884c\u5939\u95ed\u5207\u65ad\uff0c\u5b8c\u6574\u5207\u9664\u80c6\u56ca\uff0c\u672f\u540e\u51b2\u6d17\u8179\u8154\uff0c\u7559\u7f6e\u5f15\u6d41\u7ba1\u4e00\u6839\uff0c\u4e8e\u8110\u4e0b\u7a7f\u51fa\u3002" },
        { heading: "\u62df\u65bd\u9ebb\u9189\u65b9\u5f0f", content: "\u5168\u8eab\u9ebb\u9189\uff0c\u6c14\u7ba1\u63d2\u7ba1\uff0c\u7ef4\u6301\u672f\u4e2d\u751f\u547d\u4f53\u5f81\u5e73\u7a33\uff0c\u672f\u6bd5\u62d4\u7ba1\u540e\u9001\u590d\u82cf\u5ba4\u89c2\u5bdf\u3002" },
        { heading: "\u6ce8\u610f\u4e8b\u9879", content: "1. \u672f\u4e2d\u6ce8\u610f\u4fdd\u62a4\u80c6\u603b\u7ba1\u53ca\u5468\u56f4\u8840\u7ba1\u7ed3\u6784\uff0c\u907f\u514d\u635f\u4f24\uff1b2. \u672f\u4e2d\u82e5\u53d1\u73b0\u80c6\u56ca\u4e0e\u5468\u56f4\u7ec4\u7ec7\u7c98\u8fde\u4e25\u91cd\uff0c\u5e94\u8c28\u614e\u64cd\u4f5c\uff0c\u5fc5\u8981\u65f6\u8f6c\u4e3a\u5f00\u8179\u624b\u672f\uff1b3. \u672f\u540e\u5bc6\u5207\u76d1\u6d4b\u751f\u547d\u4f53\u5f81\uff0c\u6ce8\u610f\u6709\u65e0\u51fa\u8840\u3001\u80c6\u6f0f\u7b49\u5e76\u53d1\u75c7\uff1b4. \u672f\u540e\u7b2c1\u5929\u9f13\u52b1\u65e9\u671f\u4e0b\u5e8a\u6d3b\u52a8\uff0c\u4fc3\u8fdb\u80a0\u8815\u52a8\u6062\u590d\uff1b5. \u5f15\u6d41\u6db2\u91cf\u53ca\u6027\u8d28\u9700\u6bcf\u65e5\u8bb0\u5f55\uff0c\u5f15\u6d41\u91cf<10ml/d\u4e14\u989c\u8272\u6e05\u4eae\u53ef\u8003\u8651\u62d4\u9664\u3002" },
        { heading: "\u624b\u672f\u8005\u672f\u524d\u67e5\u770b\u60a3\u8005\u60c5\u51b5", content: "2024\u5e744\u67085\u65e5\uff0c\u4e3b\u5200\u533b\u5e08\u5f20\u4f1f\u4e3b\u4efb\u533b\u5e08\u672f\u524d\u67e5\u623f\uff0c\u8be6\u7ec6\u8be2\u95ee\u75c5\u53f2\uff0c\u590d\u67e5\u4f53\u5f81\uff0c\u786e\u8ba4\u60a3\u8005\u7cbe\u795e\u72b6\u6001\u826f\u597d\uff0c\u5fc3\u80ba\u529f\u80fd\u4ee3\u507f\uff0c\u65e0\u53d1\u70ed\uff0c\u65e0\u9ec4\u75b8\uff0c\u8179\u90e8\u65e0\u660e\u663e\u8179\u819c\u523a\u6fc0\u5f81\u3002\u518d\u6b21\u5411\u60a3\u8005\u53ca\u5bb6\u5c5e\u544a\u77e5\u624b\u672f\u98ce\u9669\u3001\u66ff\u4ee3\u65b9\u6848\u53ca\u9884\u540e\uff0c\u7b7e\u7f72\u300a\u624b\u672f\u77e5\u60c5\u540c\u610f\u4e66\u300b\u53ca\u300a\u9ebb\u9189\u77e5\u60c5\u540c\u610f\u4e66\u300b\u3002\u8bc4\u4f30\u8ba4\u4e3a\u60a3\u8005\u7b26\u5408\u624b\u672f\u6761\u4ef6\uff0c\u51b3\u5b9a\u4e8e\u6b21\u65e5\u884c\u8179\u8154\u955c\u80c6\u56ca\u5207\u9664\u672f\u3002" }
      ],
      focusPoints: ["\u5b8c\u6574\u8986\u76d6\u672f\u524d\u5c0f\u7ed3\u516d\u5927\u8981\u7d20"]
