      focusPoints: ["\u624b\u672f\u98ce\u9669\u8bc4\u4f30\u8868\u5185\u5bb9\u5b8c\u6574\uff0c\u6db5\u76d6\u6240\u6709\u5173\u952e\u9879\u76ee", "\u5404\u76f8\u5173\u8d23\u4efb\u4eba\u7b7e\u5b57\u9f50\u5168\u4e14\u4fe1\u606f\u6e05\u6670"]
